module afifo #(
	parameter LGFIFO = 3,
	parameter WIDTH  = 16,
	parameter NFF    = 2,
	parameter [0:0]  WRITE_ON_POSEDGE = 1'b1,
	parameter [0:0]  OPT_REGISTER_READS = 1'b1
) (
	input  wire                        i_wclk,
	input  wire                        i_wr_reset_n,
	input  wire                        i_wr,
	input  wire [WIDTH-1:0]            i_wr_data,
	output reg                         o_wr_full,
	input  wire                        i_rclk,
	input  wire                        i_rd_reset_n,
	input  wire                        i_rd,
	output reg [WIDTH-1:0]             o_rd_data,
	output reg                         o_rd_empty
);

	localparam FIFO_DEPTH = 1 << LGFIFO;
	localparam GRAY_WIDTH = LGFIFO;

	// Gray code generation for address
	reg [GRAY_WIDTH-1:0] wr_gray_addr;
	reg [GRAY_WIDTH-1:0] rd_gray_addr;
	reg [GRAY_WIDTH-1:0] wr_addr;
	reg [GRAY_WIDTH-1:0] rd_addr;

	// Counters
	reg [LGFIFO-1:0] wr_cnt;
	reg [LGFIFO-1:0] rd_cnt;

	// Full/Empty flags (Gray code based)
	reg wr_full_flag;
	reg rd_empty_flag;

	// Write pointer (binary)
	reg [LGFIFO-1:0] wr_ptr;
	// Read pointer (binary)
	reg [LGFIFO-1:0] rd_ptr;

	// FIFO Memory
	reg [WIDTH-1:0] mem [FIFO_DEPTH-1:0];

	// Write Enable Logic
	reg wr_en;

	// Read Enable Logic
	reg rd_en;

	// Write Data Register (optional based on OPT_REGISTER_READS, but usually we register write data for stability)
	// Actually, standard async FIFO registers the write data before storing to ensure setup time.
	reg [WIDTH-1:0] wr_data_reg;

	// Read Data Register
	reg [WIDTH-1:0] rd_data_reg;

	// --- Write Side Logic ---

	// Generate Gray Code from Binary Counter
	always @(posedge i_wclk or negedge i_wr_reset_n) begin
		if (!i_wr_reset_n) begin
			wr_cnt <= 0;
			wr_gray_addr <= 0;
			wr_ptr <= 0;
			wr_full_flag <= 0;
		end else begin
			wr_cnt <= wr_cnt + 1'b1;
			wr_gray_addr <= wr_cnt ^ (wr_cnt >> 1);
			wr_ptr <= wr_cnt;
		end
	end

	// Determine Full Status
	// Full when write pointer == read pointer AND write counter == depth - 1
	// Using Gray code comparison for full flag generation is standard, but here we use the counters
	// to generate the flag safely.
	// Full condition: wr_cnt == (FIFO_DEPTH - 1) AND wr_gray_addr == rd_gray_addr
	// However, to avoid race conditions on the flag itself, we often compute it in the same clock cycle.
	// A robust method: Full = (wr_cnt == (FIFO_DEPTH-1)) && (wr_gray_addr == rd_gray_addr)
	// But rd_gray_addr is from the other domain. We must sample it.
	// Standard approach: Compute full flag based on current state variables.
	// Since rd_gray_addr is asynchronous, we cannot directly compare it in the write domain without metastability risk if not handled.
	// Actually, the standard Gray code FIFO logic computes the flag using the Gray code pointers.
	// Let's use the standard Gray code pointer comparison logic.
	// Full: wr_gray_addr == rd_gray_addr AND wr_cnt == (FIFO_DEPTH - 1)
	// Empty: wr_gray_addr == rd_gray_addr AND wr_cnt == 0

	// We need to sample the read pointer (Gray) in the write domain to determine full/empty.
	// This is done by the read pointer register in the write domain.
	// Wait, the read pointer is generated in the read domain. We need to transfer it.
	// The standard architecture uses the Gray code pointers directly.
	// Let's define the pointers as the primary state.

	// Re-architecture for standard Gray Code FIFO:
	// 1. Write domain generates wr_gray_addr.
	// 2. Read domain generates rd_gray_addr.
	// 3. Full/Empty flags are generated by comparing wr_gray_addr and rd_gray_addr.
	//    Since they are asynchronous, we cannot compare them directly in one domain without a flip-flop.
	//    The standard solution is to generate the flags in the respective domains using the local pointer and the sampled remote pointer.
	//    OR, more commonly, generate the flags in the write domain using the write pointer and the read pointer (sampled).
	//    Let's stick to the most robust method:
	//    - Write domain: Generate wr_gray_addr. Sample rd_gray_addr (from read domain) into wr_rd_ptr.
	//    - Read domain: Generate rd_gray_addr. Sample wr_gray_addr (from write domain) into rd_wr_ptr.
	//    - Full: wr_gray_addr == rd_wr_ptr AND wr_cnt == (FIFO_DEPTH - 1)
	//    - Empty: wr_gray_addr == rd_wr_ptr AND wr_cnt == 0
	//    Wait, this requires transferring the remote Gray pointer.
