		if (!i_wr_reset_n) begin
			wr_rd_ptr <= 0;
		end else begin
			wr_rd_ptr <= rd_gray_addr;
		end
	end

	// Read Domain: Sample Write Pointer
	always @(posedge i_rclk or negedge i_rd_reset_n) begin
		if (!i_rd_reset_n) begin
			rd_wr_ptr <= 0;
		end else begin
			rd_wr_ptr <= wr_gray_addr;
		end
	end

	// Write Logic
	always @(posedge i_wclk or negedge i_wr_reset_n) begin
		if (!i_wr_reset_n) begin
			o_wr_full <= 0;
			wr_en <= 0;
			wr_data_reg <= 0;
		end else begin
			// Check Full
			// Full if wr_cnt == (FIFO_DEPTH-1) AND wr_gray_addr == wr_rd_ptr
			if (wr_cnt == (FIFO_DEPTH - 1) && wr_gray_addr == wr_rd_ptr)
				o_wr_full <= 1'b1;
			else
				o_wr_full <= 1'b0;

			// Write Enable
