		if (!i_wr_reset_n) begin
			wr_cnt <= 0;
			wr_gray_addr <= 0;
		end else begin
			wr_cnt <= wr_cnt + 1'b1;
			wr_gray_addr <= wr_cnt ^ (wr_cnt >> 1);
		end
	end

